package com.graduation.lostfound.domain;import com.graduation.lostfound.auth.AuthService;import com.graduation.lostfound.common.ApiException;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/claims")public class ClaimController{private final ClaimRequestRepository repo;private final LostFoundPostRepository posts;private final AuthService auth;public ClaimController(ClaimRequestRepository r,LostFoundPostRepository p,AuthService a){repo=r;posts=p;auth=a;}public record Create(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long postId,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=2000) String proof){}@PostMapping public ClaimRequest create(@jakarta.validation.Valid @RequestBody Create x){var u=auth.currentUser();var p=posts.findById(x.postId()).orElseThrow(()->ApiException.notFound("信息不存在"));if(!"OPEN".equals(p.getStatus()))throw ApiException.badRequest("该信息已关闭");if(repo.existsByPostIdAndUserId(p.getId(),u.getId()))throw ApiException.badRequest("已提交过认领");var c=new ClaimRequest();c.setPostId(p.getId());c.setUserId(u.getId());c.setProof(x.proof());c.setStatus("PENDING");return repo.save(c);}@GetMapping public List<ClaimRequest> list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}@PatchMapping("/{id}/approve")@PreAuthorize("hasRole('ADMIN')")@Transactional public ClaimRequest approve(@PathVariable Long id){var c=repo.findById(id).orElseThrow(()->ApiException.notFound("认领不存在"));var p=posts.findById(c.getPostId()).orElseThrow();c.setStatus("APPROVED");p.setStatus("RESOLVED");posts.save(p);return repo.save(c);}}
